/**
 *
 * ContextMenuItem is a pure context menu item.
 * For checkable items use ContextMenuCheckboxItem or ContextMenuRadioItem.
 *
 * [Live Demo](https://www.primereact.org/contextmenu/)
 *
 * @module ContextMenuItem
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuItemSelectEvent } from '../menu/MenuRoot.types';
import type { ContextMenuPortalInstance } from './ContextMenuPortal.types';
import type { ContextMenuRootInstance } from './ContextMenuRoot.types';
import type { ContextMenuSubmenuInstance } from './ContextMenuSubmenu.types';
/**
 * Defines passthrough(pt) options type in ContextMenuItem component.
 */
export type ContextMenuItemPassThroughType<E> = PassThroughType<ContextMenuItemInstance, E>;
/**
 * Defines passthrough(pt) options of ContextMenuItem component.
 */
export interface ContextMenuItemPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ContextMenuItemPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in ContextMenuItem component.
 */
export interface ContextMenuItemProps extends BaseComponentProps<ContextMenuItemInstance, unknown, ContextMenuItemPassThrough> {
    /**
     * When present, it specifies that the item should be disabled.
     */
    disabled?: boolean | undefined;
    /**
     * Semantic value that uniquely identifies this item within the menu.
     * Used to generate a deterministic DOM id. When not provided, auto-generated.
     */
    value?: string;
    /**
     * Whether the menu should close when this item is activated. Overrides the
     * `closeOnSelect` setting on `ContextMenu.Root` for this item only.
     * @default true
     */
    closeOnSelect?: boolean | undefined;
    /**
     * Callback fired when the item is activated (click or keyboard). Calling
     * `event.preventDefault()` keeps the menu open regardless of
     * `closeOnSelect`.
     */
    onSelect?: (event: MenuItemSelectEvent) => void;
}
/**
 * Defines valid state in ContextMenuItem component.
 */
export interface ContextMenuItemState {
}
/**
 * Defines the methods and properties exposed by ContextMenuItem component.
 */
export interface ContextMenuItemExposes {
    /**
     * Instance of the ContextMenu component.
     */
    contextmenu: ContextMenuRootInstance | undefined | null;
    /**
     * Instance of the ContextMenuSubmenu component.
     */
    submenu: ContextMenuSubmenuInstance | undefined | null;
    /**
     * Instance of the ContextMenuPortal component.
     */
    portal: ContextMenuPortalInstance | undefined | null;
    /**
     * ID of the item element.
     */
    itemId: string | undefined;
    /**
     * Whether the item is focused or not.
     */
    focused: boolean;
    /**
     * Whether the item is disabled or not.
     */
    isDisabled: boolean;
}
/**
 * Instance of ContextMenuItem component.
 */
export type ContextMenuItemInstance = ComponentInstance<ContextMenuItemProps, ContextMenuItemState, ContextMenuItemExposes>;
